import re
def readable(x):
 if isinstance(x,str):
  return re.sub(r'(?<=[0-9])(?=[A-Za-zÇĞİÖŞÜçğıöşü])|(?<=[A-Za-zÇĞİÖŞÜçğıöşü])(?=[0-9])',' ',x)
 if isinstance(x,list):return [readable(v) for v in x]
 if isinstance(x,dict):return {k:readable(v) for k,v in x.items()}
 return x
CASES[12:]=[readable(c) for c in CASES[12:]]
